    "explanation": "太陽光以短波輻射（紫外線、可見光）的方式傳送能量給地球，這些能量到達地球後，約三分之一會反射回外太空，扣除少部分被大氣吸收的能量，地表吸收了大約三分之二的能量。為了平衡這些吸收的能量，地表會再以長波輻射的形式（紅外線）將能量再次射出；而由地表輻射出的能量又進一步為溫室氣體吸收，溫室氣體再次將能量輻射回地球，就是所謂的溫室效應。"
