    "explanation": "災害對策的根本為「自助」，無論面臨何種狀況，「守護自身性命」為永遠不變的法則，如在災害中失去生命或受傷，則無法幫助家人或鄰居，更無法執行防災士的救災業務。\n日本阪神大地震中，約有8成以上的死者因地震後被壓在倒塌的房屋、家具或電視下而於短時間內死亡，為避免此悲劇重演，平時便應加強住宅的耐震性或固定家具等以未雨綢繆。\n在2011年3月11日東日本大震災中，即有不少民眾因平時做好家具之固定、儲備物資、海嘯避難訓練等，因而在地震發生時以自身之力將傷害降至最低。\n災害中，防災士如不幸喪生或受重傷，則無法救助家人、鄰居、或職場同事，亦無法對災後重建或振興有所貢獻，因此，防災士平時便應做好萬全準備、學習防災及減災的相關知識和技能，並持續提升自我能力。\n『以「幫助他人」為目標，而非成為一個「接受他人幫助的人」。』"
