    "explanation": "一、隨身攜帶手冊、緊急連絡卡：\n一但發生大規模災害，交通通訊往往相當混亂且可能中斷，家庭成員的團聚，常常會有所困難，因此平時應做好緊急連絡卡，以備不時之需。\n二、緊急攜出物品之準備：\n經常性服用之藥品、常去的醫療機構聯絡方式、記有常用藥物品項之「藥物手冊」或筆記。輪椅、助聽器、老花眼鏡等當事人所必需的配備、物品。\n三、避難場所、避難路徑、聯絡方式之確認：\n平時應與家人討論災害時之避難場所、避難路徑、聯絡方式等事宜，並具體決定約定場所與共通的聯絡人（其他縣市的親戚等）。\n四、準備看護犬等寵物所應之配備物品"
