      "二級警戒：發布淹水警戒之鄉（鎮、市、區）如持續降雨，其轄內易淹水村里及道路可能在三小時內開始積淹水",
      "一級警戒：發布淹水警戒之鄉（鎮、市、區）如持續降雨，其轄內易淹水村里及道路可能已經開始積淹水"
