    "answer": "A",
    "explanation": "【重要】\n1、切勿聽信謠言和傳播謠言，有疑慮時，應直撥166或167氣象資訊語音專線、收聽廣播、收看電視或瀏覽中央氣象局網頁（www.cwb.gov.tw）或應用氣象局開發之Facebook、報天氣粉絲團及生活氣象APP，以取得有關颱風之最新消息。\n2、假如看不到報紙、沒有收音機或電視機，也沒有網路的情形下，無法知道颱風的消息，可以根據前面所說的幾種颱風將要來臨的預兆（第75問），事先加以防範，千萬不可聽信謠言；亦可至當地派出所或鄉公所去詢問，他們會告知正確的颱風消息。\n3、教學單位應主動發布消息，避免謠言散播，動搖人心：\n4、建立並恪遵學校發言人制度，主動發布新聞及詳細傷害情況。\n5、避免自行使用通信線路或頻道，因其必須管制做為救災最優先使用。\n6、如果無法一一通知家長，應善用傳播媒體，隨時更新學生受傷害資料，使家長放心。"
