      "興建建築物時最好能與鄰棟建築物保持一定的距離，不然地震時可能會因為搖晃，造成彼此碰撞並產生破壞",
      "狀如正方形、矩形或圓柱形等越簡單、對稱、規則，而且寬度均勻變化的建築物，在地震時受力比較均勻，搖晃的程度較輕微，所以這一類房屋的耐震強度比較高",
      "任意拆除或變更原來的牆、柱、樑、板之設計，對於建築物的結構不會產生負面影響"
