    "explanation": "（一）注意海嘯警報與訊息：地震後隨時注意海嘯警報及收聽相關訊息。\n（二）遠離海邊、停止活動：盡速離開海嘯可能影響之區域，停止各種海上活動及出海捕魚。\n（三）盡量往內陸或高處疏散避難：進行海嘯疏散避難時，應優先考慮附近堅固高樓，若無，應往內陸高處方向避難。\n（四）短距離避難避免使用車輛：使用車輛容易造成交通阻塞，若車輛被海嘯捲入，人員更不易脫困。\n（五）切勿立即返家，注意相關訊息：海嘯第一波退去後，後續可能有第二波海嘯。"
