    "explanation": "（一）政府會經由各種媒體管道通知民眾警戒：\n1、固定式警報站\n2、防救災訊息服務發送平臺\n3、巡迴廣播車\n4、民政廣播系統\n5、防空警報系統及警察廣播電臺\n6、媒體播報（電視、網路）\n7、災防告警系統－細胞廣播服務（CBS）\n（二）採取掩蔽措施：\n事故警報發布後，保護自己最好的方法就是減少與輻射接觸的機會；已經在家裡者，應關緊門窗，空調設備調整為室內循環模式，收看電視或收聽廣播以了解進一步的事故情況，若在室外，應進入附近有門窗的鋼筋水泥建築物躲避或迅速回家，緊閉門窗，並脫除衣物、淋浴以去除輻射塵；如果是在車內，而附近又沒有適當的掩蔽場所，則應關緊車窗及空調設備，盡速離開事故影響區域；原則上，曝露在外得食物及飲用水不要食用，放置於室內的飲用水或食物則可安心使用，如圖101所示。\n（三）服用碘片\n核子事故發生時，如有大量放射性碘經由呼吸道進入體內，將會傷害甲狀腺，而碘片可阻止游離碘集入甲狀腺，只要有足夠的量就可以阻止放射性碘進入甲狀腺。但碘片不是萬靈丹，對於核子事故發生時所釋放之其他放射性物質並無保護作用，且需在政府下達命令後才能服用。為防範核能電廠緊急意外事故發生時可能因放射性碘洩漏造成甲狀腺危害，由於少部分人對碘片會產生副作用，因此碘片之服用必須等政府通知。此外，由於輻射游離碘對於40歲以上成人甲狀腺之傷害或引發甲狀腺癌之機率極低，因此，建議40歲以上成人除非必要，否則不建議服用碘片，依據政府指示服用碘片，成人每日一錠、孕婦及3-12歲兒童每日1/2錠、未滿3歲兒童每日1/4錠。\n（四）疏散與收容安置：\n當核子事故發生，原能會將立即與相關部會共同成立中央災害應變中心，地方政府也會成立地方災害應變中心，進行緊急應變作業與民眾防護措施（掩蔽、疏散、服用碘片等），提供即時環境輻射與食品飲水採樣檢測資訊，並定期發布最新訊息，供民眾了解。\n1、預防性疏散：\n核子事故發生初期，尚未有放射性物質外釋時，為確保後續應變作業順遂執行，將優先針對緊鄰核能電廠區域之民眾進行預防性疏散措施，同時，針對緊急應變計畫區內弱勢民眾、特定族群（醫院、學校、老人安養與養護中心等）優先調派適宜載具，於準備妥適後疏散至指定收容場所，若有行動不便者，可於家中明顯處放置「我需要協助」指示牌，以利救災人員第一時間提供協助；至於遊客部份則將於事故發生初始，即通知先行離開，事故時之疏散將以當地民眾為主。\n2、國中小學生疏散：\n因應核子事故發生是有時序及階段性，將依風險概念進行由內至外及下風向進行階段性疏散作業，未接獲政府下令疏散之區域則以掩蔽措施為主，以避免因匆促及混亂之疏散造成不必要生命財產損失，如後續事故演進有惡化及擴大之趨勢，再依此概念擴大疏散範圍。\n3、下風向、階段性之疏散：\n因應核子事故發生是有時序及階段性，將依風險概念進行由內至外及下風向進行階段性疏散作業，未接獲政府下令疏散之區域則以掩蔽措施為主，以避免因匆促及混亂之疏散造成不必要生命財產損失，如後續事故演進有惡化及擴大之趨勢，再依此概念擴大疏散範圍。\n4、接獲疏散通知怎麼辦：\n事故若持續惡化，中央災害應變中心經評估後會下令執行疏散行動並透過電視、收音機持續發放疏散通知，接獲疏散通知時，民眾準備簡單行李（例如個人證件、手機、簡單乾糧、飲用說及換洗衣物、帽子、手套、口罩、收音機、手電筒及備用電池、急救包、個人藥物等），關掉瓦斯、電器開關及門窗，遵循應變人員指示，前往緊急應變計畫區（Emergency Planning Zone, EPZ）內平時即規劃設置完成集結地點，搭乘備妥之疏散車輛，萬一放射性物質外釋，應先前往防護站進行偵檢除污，防護站設置目的係為有效掌握EPZ內疏散民眾的人數與動向，保障民眾的健康與安全。"
